                || ($report['measurement_type'] ?? null) !== 'self_report_trait_mixed_ei'
                || ($authority['schema_version'] ?? null) !== 'fap.eq60.private_result_authority.v1'
                || ($authority['authority_id'] ?? null) !== Eq60PackLoader::AUTHORITY_ID
                || ($authority['pack_id'] ?? null) !== 'EQ_60' || ($authority['pack_version'] ?? null) !== 'v1'
                || ($authority['locale'] ?? null) !== $locale
                || ($binding['schema_version'] ?? null) !== 'fap.eq60.snapshot_binding.v1'
                || ($binding['locale'] ?? null) !== $locale || ($binding['pack_version'] ?? null) !== 'v1'
                || ! is_string($binding['canonical_payload_sha256'] ?? null)
                || preg_match('/\A[a-f0-9]{64}\z/', $binding['canonical_payload_sha256']) !== 1
                || ($binding['canonical_authority_identity'] ?? null) !== $authority['authority_id']
                || ! isset(self::PACKS[$authority['source_hash'] ?? ''])
                || self::PACKS[$authority['source_hash']] !== ($authority['compiled_hash'] ?? null)) {
                throw new DomainException('historical_eq_report_not_supported');
            }
            foreach (['release_id', 'source_hash', 'compiled_hash'] as $field) {
                if (($binding['canonical_'.$field] ?? null) !== ($authority[$field] ?? null)) {
                    throw new DomainException('original_binding_conflicting');
                }
            }
            $currentAuthority = $this->loader->authority('v1', $locale);
            $local = app()->environment(['local', 'testing']) && ($authority['mode'] ?? null) === 'local_repo_compiled'
                && ($authority['release_id'] ?? null) === ''
                && $authority['source_hash'] === $currentAuthority['source_hash']
                && $authority['compiled_hash'] === $currentAuthority['compiled_hash'];
            if (! $local && (($authority['mode'] ?? null) !== 'canonical_active_release'
                || ! is_string($authority['release_id'] ?? null) || $authority['release_id'] === ''
                || ! DB::table('content_pack_releases')->where('id', $authority['release_id'])->where('to_pack_id', 'EQ_60')
                    ->where('pack_version', 'v1')->where('status', 'success')->where('content_hash', $authority['source_hash'])
                    ->where('compiled_hash', $authority['compiled_hash'])->exists())) {
                throw new DomainException('historical_eq_report_not_supported');
            }
            // Composer payload identity is preserved as declared. Snapshot JSON storage
            // and response projections can reorder keys or normalize 1.0 to 1; their
            // decoded read-view digest below is a different identity, not this hash.
            $compiled = $this->loader->loadReportAssets('v1');
            if (($compiled['source_hash'] ?? null) !== $currentAuthority['source_hash']) {
                throw new DomainException('reading_source_conflicting');
            }
            $reading = $report;
            $applied = [];
            foreach (json_decode(self::SELECTORS, true, 64, JSON_THROW_ON_ERROR) as $row) {
                $after = $this->at($compiled, $row['source_path']);
                if (! is_string($after) || ! hash_equals($row['after_sha256'], hash('sha256', $after))) {
                    throw new DomainException('reading_source_drift');
                }
                foreach ($row['slots'] as $slot) {
                    if ($slot['locale'] !== '*' && $slot['locale'] !== $locale) {
                        continue;
                    }
                    if (isset($slot['route_id']) && data_get($reading, 'interpretation.route_id') !== $slot['route_id']) {
                        continue;
                    }
                    if (isset($slot['asset_path']) && $this->at($reading, [...$slot['asset_path'], 'id']) !== $slot['asset_id']) {
                        continue;
                    }
                    if (isset($slot['skip_empty_parent']) && $this->at($reading, $slot['skip_empty_parent']) === []) {
                        continue;
                    }
                    $path = $slot['path'] ?? null;
                    if (isset($slot['array'])) {
                        $items = $this->at($reading, $slot['array']);
                        if (! is_array($items)) {
                            throw new DomainException('reading_asset_structure_invalid');
                        }
                        $indices = array_keys(array_filter($items, static fn ($item): bool => is_array($item) && ($item['id'] ?? null) === $slot['asset_id']));
                        if ($indices === []) {
                            continue;
                        }
                        if (count($indices) !== 1) {
                            throw new DomainException('reading_asset_identity_ambiguous');
                        }
                        $path = [...$slot['array'], $indices[0], ...$slot['tail']];
                    }
                    $this->replace($reading, $path, $row['before'], $after, $applied);
                    if ($path === ['assets', 'quality_confidence', 'what_to_hold_lightly']
                        && array_key_exists('do_not_overread', $reading['assets']['quality_confidence'])) {
                        $this->replace($reading, ['assets', 'quality_confidence', 'do_not_overread'], $row['before'], $after, $applied);
                    }
                }
            }
            $this->neutralMechanisms($reading, $compiled, $locale, $applied);

            return ['schema_version' => 'eq60.reading_copy.v1', 'revision' => self::REVISION, 'status' => 'ready', 'locale' => $locale,
                'original_authority' => $authority, 'reading_authority' => $currentAuthority,
                'original_report_sha256' => $this->digest($report), 'projected_report_sha256' => $this->digest($reading),
                'applied_keys' => array_values(array_unique($applied)), 'report' => $reading];
        } catch (DomainException $error) {
            return ['schema_version' => 'eq60.reading_copy.v1', 'revision' => self::REVISION, 'status' => 'unavailable', 'reason' => $error->getMessage()];
        }
    }

    private function neutralMechanisms(array &$reading, array $compiled, string $locale, array &$applied): void
    {
        $route = data_get($reading, 'interpretation.route_id');
        $before = match ($route) {
            'route.eq.balanced_integrated.primary.quality_ab' => ['SA_ER_high_high', 'EM_RM_high_high'],
            'route.eq.balanced_integrated.gap_focus.quality_ab' => ['EM_RM_high_high', 'ER_RM_high_high'],
            default => null,
        };
        if ($before === null) {
            return;
        }
        $after = ['SA_ER_mixed', 'EM_RM_mixed'];
        $paths = [['interpretation', 'primary_mechanism_ids'], ['interpretation', 'selected_asset_ids', 'mechanism_ids'],
            ['asset_refs', 'mechanism_ids'], ['asset_refs', 'selected_asset_ids', 'mechanism_ids'],
            ['assets', 'personalization_route', 'selected_asset_ids', 'mechanism_ids']];
        $needsChange = false;
        foreach ($paths as $path) {
            $value = $this->at($reading, $path);
            if ($value !== $before && $value !== $after) {
                throw new DomainException('mechanism_reference_conflicting');
            }
            $needsChange = $needsChange || $value === $before;
        }
        if (! $needsChange) {
            return;
        }
        if (array_column((array) data_get($reading, 'assets.mechanisms'), 'id') !== $before) {
            throw new DomainException('mechanism_asset_identity_conflicting');
        }
        $objects = [];
        foreach (['SA_ER', 'EM_RM'] as $pair) {
            $node = $this->at($compiled, ['assets', 'mechanism_map', 'pairs', $pair, 'mixed', $locale]);
            if (! is_array($node) || $node === []) {
                throw new DomainException('reading_mechanism_missing');
            }
            $objects[] = ['id' => $pair.'_mixed', 'pair' => $pair, 'state' => 'mixed', ...$node];
        }
        foreach ($paths as $path) {
            $leaf = &$reading;
            foreach ($path as $key) {
                $leaf = &$leaf[$key];
            }
            $leaf = $after;
            unset($leaf);
        }
        $reading['assets']['mechanisms'] = $objects;
        $applied[] = 'neutral_mechanism_references_and_resolved_objects';
    }

    private function replace(array &$reading, array $path, string $before, string $after, array &$applied): void
    {
        $value = $this->at($reading, $path);
        if ($value === $after) {
            return;
        }
        if ($value !== $before) {
            throw new DomainException('reading_copy_prestate_unknown');
        }
        $leaf = &$reading;
        foreach ($path as $key) {
            $leaf = &$leaf[$key];
        }
        $leaf = $after;
        $applied[] = json_encode($path, JSON_THROW_ON_ERROR);
    }

    private function at(mixed $value, array $path): mixed
    {
        foreach ($path as $key) {
            if (! is_array($value) || ! array_key_exists($key, $value)) {
                return null;
            }
            $value = $value[$key];
        }

        return $value;
    }

    private function digest(array $value): string
    {
        return hash('sha256', \App\Services\ContentPromotion\PromotionContextFactory::canonicalJson($value));
    }
}
